1	/**
2	 * 规范化编码与签名摘要。
3	 *
4	 * 各类操作使用不同的域分隔标签，签名互不兼容（任一类型的签名都不能用于其他类型）：
5	 *   - 普通交易：     "safe-wallet/tx/v1"
6	 *   - 原子批量交易： "safe-wallet/tx-batch/v1"
7	 *   - 策略变更：     "safe-wallet/policy-change/v1"
8	 *   - 任务取消：     "safe-wallet/cancel/v1"
9	 *
10	 * 编码规则（全部大端）：
11	 *   encBytes(b)  = uint32(len) || b
12	 *   encStr(s)    = uint32(len) || utf8(s)
13	 *   encUint(n)   = n 的定长 32 字节大端表示
14	 *   encList(xs)  = uint32(count) || concat(encBytes(x))
15	 *
16	 * 普通交易载荷不包含策略版本字段（保持既有交易格式不变）；
17	 * 批量交易载荷绑定钱包标识、nonce、截止时间，以及按顺序编码的全部调用
18	 * （每调用固定按“收款地址 || 金额 || data”编码，再以 encList 绑定项数与顺序）；
19	 * 策略变更载荷显式绑定钱包标识、操作标签、当前版本、新所有者、新确认数、nonce、截止时间。
20	 */
21	
22	import { sha256, hexToBytes, type Address } from './crypto.ts';
23	
24	const TAG_TX = 'safe-wallet/tx/v1';
25	const TAG_TX_BATCH = 'safe-wallet/tx-batch/v1';
26	const TAG_POLICY_CHANGE = 'safe-wallet/policy-change/v1';
27	const TAG_CANCEL = 'safe-wallet/cancel/v1';
28	
29	// ---------- 编码原语 ----------
30	
31	export function encBytes(data: Uint8Array): Buffer {
32	  const b = Buffer.from(data);
33	  const out = Buffer.alloc(4 + b.length);
34	  out.writeUInt32BE(b.length, 0);
35	  b.copy(out, 4);
36	  return out;
37	}
38	
39	export function encStr(s: string): Buffer {
40	  return encBytes(Buffer.from(s, 'utf8'));
41	}
42	
43	export function encUint(n: bigint | number): Buffer {
44	  const v = BigInt(n);
45	  if (v < 0n) throw new Error('cannot encode negative integer');
46	  if (v >> 256n !== 0n) throw new Error('integer exceeds 32 bytes');
47	  const out = Buffer.alloc(32);
48	  let x = v;
49	  for (let i = 31; i >= 0; i--) {
50	    out[i] = Number(x & 0xffn);
51	    x >>= 8n;
52	  }
53	  return out;
54	}
55	
56	export function encList(items: Uint8Array[]): Buffer {
57	  const head = Buffer.alloc(4);
58	  head.writeUInt32BE(items.length, 0);
59	  return Buffer.concat([head, ...items.map(encBytes)]);
60	}
61	
62	function digest(tag: string, parts: Buffer[]): Buffer {
63	  return sha256(Buffer.concat([encStr(tag), ...parts]));
64	}
65	
66	// ---------- 请求类型 ----------
67	
68	export interface TransactionRequest {
69	  /** 钱包标识（部署时确定；参与签名绑定，防止跨钱包重放） */
70	  walletId: string;
71	  nonce: bigint;
72	  /** Unix 秒级截止时间（也接受毫秒级大数；语义由调用方约定，引擎按数值比较） */
73	  deadline: bigint;
74	  to: Address;
75	  value: bigint;
76	  data: Uint8Array;
77	}
78	
79	export interface PolicyChangeRequest {
80	  walletId: string;
81	  /** 提交时绑定的当前策略版本 */
82	  version: bigint;
83	  nonce: bigint;
84	  deadline: bigint;
85	  newOwners: Address[];
86	  newConfirmations: bigint;
87	}
88	
89	/** 批量交易中的单次调用：收款地址、金额、附带数据 */
90	export interface BatchTransactionCall {
91	  to: Address;
92	  value: bigint;
93	  data: Uint8Array;
94	}
95	
96	export interface TransactionBatchRequest {
97	  /** 钱包标识（部署时确定；参与签名绑定，防止跨钱包重放） */
98	  walletId: string;
99	  nonce: bigint;
100	  deadline: bigint;
101	  /** 有序调用列表（1..64 项）；顺序参与签名，不得改变 */
102	  calls: BatchTransactionCall[];
103	}
104	
105	export interface CancellationRequest {
106	  walletId: string;
107	  /** 目标任务的签名摘要（hex）：把取消请求绑定到唯一任务，防止改绑其他任务 */
108	  taskDigest: string;
109	  nonce: bigint;
110	  deadline: bigint;
111	}
112	
113	function walletIdBytes(walletId: string): Buffer {
114	  // 钱包标识统一按 UTF-8 参与签名绑定（任意字符串均可）
115	  return Buffer.from(walletId, 'utf8');
116	}
117	
118	function deadlineToBigint(d: bigint | number): bigint {
119	  return BigInt(d);
120	}
121	
122	/** 普通交易的签名摘要（不含策略版本字段） */
123	export function hashTransaction(req: {
124	  walletId: string;
125	  nonce: bigint | number;
126	  deadline: bigint | number;
127	  to: Address;
128	  value: bigint | number;
129	  data: Uint8Array;
130	}): Buffer {
131	  return digest(TAG_TX, [
132	    encBytes(walletIdBytes(req.walletId)),
133	    encUint(req.nonce),
134	    encUint(deadlineToBigint(req.deadline)),
135	    encBytes(hexToBytes(req.to)),
136	    encUint(req.value),
137	    encBytes(req.data),
138	  ]);
139	}
140	
141	/**
142	 * 原子批量普通交易的签名摘要：绑定钱包标识、nonce、截止时间，以及按顺序编码的全部调用。
143	 * 每个调用固定按“收款地址 || 金额 || data”编码为一段，再以 encList 绑定项数与顺序：
144	 * 任一调用的收款方/金额/data 变化，或调用顺序/项数变化，都会改变摘要。
145	 */
146	export function hashTransactionBatch(req: {
147	  walletId: string;
148	  nonce: bigint | number;
149	  deadline: bigint | number;
150	  calls: readonly {
151	    to: Address;
152	    value: bigint | number;
153	    data: Uint8Array;
154	  }[];
155	}): Buffer {
156	  const encodedCalls = req.calls.map((call) =>
157	    Buffer.concat([
158	      encBytes(hexToBytes(call.to)),
159	      encUint(call.value),
160	      encBytes(call.data),
161	    ]),
162	  );
163	  return digest(TAG_TX_BATCH, [
164	    encBytes(walletIdBytes(req.walletId)),
165	    encUint(req.nonce),
166	    encUint(deadlineToBigint(req.deadline)),
167	    encList(encodedCalls),
168	  ]);
169	}
170	
171	/** 策略变更的签名摘要：显式绑定版本、新所有者与新确认数 */
172	export function hashPolicyChange(req: {
173	  walletId: string;
174	  version: bigint | number;
175	  nonce: bigint | number;
176	  deadline: bigint | number;
177	  newOwners: Address[];
178	  newConfirmations: bigint | number;
179	}): Buffer {
180	  return digest(TAG_POLICY_CHANGE, [
181	    encBytes(walletIdBytes(req.walletId)),
182	    encUint(req.version),
183	    encUint(req.nonce),
184	    encUint(deadlineToBigint(req.deadline)),
185	    encUint(req.newConfirmations),
186	    encList(req.newOwners.map((o) => hexToBytes(o))),
187	  ]);
188	}
189	
190	/** 任务取消的签名摘要：绑定钱包标识、目标任务摘要、nonce 与截止时间 */
191	export function hashCancellation(req: {
192	  walletId: string;
193	  taskDigest: string;
194	  nonce: bigint | number;
195	  deadline: bigint | number;
196	}): Buffer {
197	  return digest(TAG_CANCEL, [
198	    encBytes(walletIdBytes(req.walletId)),
199	    encBytes(hexToBytes(req.taskDigest)),
200	    encUint(req.nonce),
201	    encUint(deadlineToBigint(req.deadline)),
202	  ]);
203	}
