1	/**
2	 * 多签钱包策略引擎。
3	 *
4	 * 在阈值策略、签名收集、重放防护、FIFO 执行队列、策略变更任务与任务取消之上，新增
5	 * “原子批量普通交易”：当前所有者以阈值签名（safe-wallet/tx-batch/v1 域，绑定钱包标识、
6	 * nonce、截止时间与按顺序编码的全部调用）提交一个有序调用列表（1..64 项）。
7	 * 批量任务只入队一个队列任务、只消费一个 nonce；执行时整批成功产生一个 transfer-batch
8	 * 回执（不产生部分执行回执），失败则整批不生效。批量任务沿用同一 FIFO 队列、取消语义与
9	 * 终态幂等；单笔交易 / 策略变更 / 取消签名均不能授权批量交易。
10	 */
11	
12	import {
13	  type Address,
14	  ZERO_ADDRESS,
15	  isZeroAddress,
16	  normalizeAddress,
17	  recoverAddress,
18	} from './crypto.ts';
19	import {
20	  hashCancellation,
21	  hashPolicyChange,
22	  hashTransaction,
23	  hashTransactionBatch,
24	  type PolicyChangeRequest,
25	  type TransactionBatchRequest,
26	  type TransactionRequest,
27	} from './encoding.ts';
28	import {
29	  InvalidCancellation,
30	  InvalidPolicyChange,
31	  InvalidTransaction,
32	  InvalidTransactionBatch,
33	  NonceAlreadyUsedError,
34	  RequestExpired,
35	  PolicyConflict,
36	  InvalidQueueStateError,
37	  TaskCancellationConflict,
38	  TaskNotFoundError,
39	} from './errors.ts';
40	import { ExecutionQueue, type QueueTask } from './queue.ts';
41	
42	// ---------- 任务载荷 ----------
43	
44	export type WalletTaskPayload =
45	  | {
46	      kind: 'transaction';
47	      deadline: bigint;
48	      to: Address;
49	      value: bigint;
50	      data: Uint8Array;
51	    }
52	  | {
53	      kind: 'transaction-batch';
54	      deadline: bigint;
55	      /** 有序调用；顺序即执行顺序，执行回执按同一顺序给出 */
56	      calls: BatchCall[];
57	    }
58	  | {
59	      kind: 'policy-change';
60	      deadline: bigint;
61	      /** 提交时绑定的策略版本；执行时必须仍等于当前版本 */
62	      version: bigint;
63	      newOwners: Address[];
64	      newConfirmations: bigint;
65	    };
66	
67	/** 批量任务内的单次调用（规范化后的收款地址、原金额、原始 data 副本） */
68	export interface BatchCall {
69	  to: Address;
70	  value: bigint;
71	  data: Uint8Array;
72	}
73	
74	export type WalletTask = QueueTask<WalletTaskPayload>;
75	
76	export interface PolicyState {
77	  owners: Address[];
78	  confirmations: bigint;
79	  version: bigint;
80	}
81	
82	export interface WalletOptions {
83	  id: string;
84	  owners: Address[];
85	  confirmations: bigint | number;
86	  /** 注入时钟，返回 Unix 秒；默认取系统时间 */
87	  now?: () => bigint;
88	}
89	
90	export interface TransactionSubmission {
91	  nonce: bigint | number;
92	  deadline: bigint | number;
93	  to: string;
94	  value: bigint | number;
95	  data?: Uint8Array;
96	}
97	
98	export interface PolicyChangeSubmission {
99	  version: bigint | number;
100	  nonce: bigint | number;
101	  deadline: bigint | number;
102	  newOwners: string[];
103	  newConfirmations: bigint | number;
104	}
105	
106	export interface CancellationSubmission {
107	  /** 目标任务 id（队列快照中的任务标识） */
108	  taskId: string;
109	  nonce: bigint | number;
110	  deadline: bigint | number;
111	}
112	
113	/** 批量提交中的单次调用（原始输入；地址在校验时规范化） */
114	export interface BatchCallSubmission {
115	  to: string;
116	  value: bigint | number;
117	  /** 必含的调用数据（允许零长度）；必须是 Uint8Array */
118	  data: Uint8Array;
119	}
120	
121	export interface BatchTransactionSubmission {
122	  nonce: bigint | number;
123	  deadline: bigint | number;
124	  /** 有序调用列表：非空且最多 MAX_BATCH_CALLS 项，顺序参与签名且不得改变 */
125	  calls: readonly BatchCallSubmission[];
126	}
127	
128	/** 批量交易调用数量上限（含） */
129	export const MAX_BATCH_CALLS = 64;
130	
131	function isNonNegativeInteger(n: bigint, maxBits = 256): boolean {
132	  return n >= 0n && n < 2n ** BigInt(maxBits);
133	}
134	
135	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
136	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
137	  if (typeof value === 'bigint') return value;
138	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
139	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
140	  throw new Invalid(`field "${field}" must be a non-negative integer`);
141	}
142	
143	export class MultiSigWallet {
144	  readonly id: string;
145	  private readonly now: () => bigint;
146	
147	  private owners: Address[];
148	  private readonly ownerSet: Set<Address>;
149	  private confirmations: bigint;
150	  private version: bigint;
151	
152	  /** 下一个期望 nonce（严格递增，顺序提交） */
153	  private nextNonce = 0n;
154	  /** 已消费 nonce（入队即消费；失败终态也不释放） */
155	  private readonly usedNonces = new Set<bigint>();
156	
157	  readonly queue: ExecutionQueue<WalletTaskPayload>;
158	
159	  constructor(opts: WalletOptions) {
160	    const owners = normalizeOwnerList(opts.owners);
161	    const confirmations = BigInt(opts.confirmations);
162	    if (confirmations <= 0n || confirmations > BigInt(owners.length)) {
163	      throw new InvalidPolicyChange(
164	        `initial confirmations must be within 1..owners (${owners.length}), got ${confirmations}`,
165	      );
166	    }
167	    this.id = opts.id;
168	    this.now = opts.now ?? (() => BigInt(Math.floor(Date.now() / 1000)));
169	    this.owners = owners;
170	    this.ownerSet = new Set(owners);
171	    this.confirmations = confirmations;
172	    this.version = 1n;
173	    this.queue = new ExecutionQueue((task) => this.applyTask(task));
174	  }
175	
176	  // ---------- 只读状态 ----------
177	
178	  get policy(): PolicyState {
179	    return { owners: [...this.owners], confirmations: this.confirmations, version: this.version };
180	  }
181	
182	  get policyVersion(): bigint {
183	    return this.version;
184	  }
185	
186	  get currentOwners(): Address[] {
187	    return [...this.owners];
188	  }
189	
190	  get requiredConfirmations(): bigint {
191	    return this.confirmations;
192	  }
193	
194	  get expectedNonce(): bigint {
195	    return this.nextNonce;
196	  }
197	
198	  isOwner(address: string): boolean {
199	    const a = normalizeAddress(address);
200	    return a !== null && this.ownerSet.has(a);
201	  }
202	
203	  isNonceUsed(nonce: bigint | number): boolean {
204	    return this.usedNonces.has(BigInt(nonce));
205	  }
206	
207	  get tasks(): readonly WalletTask[] {
208	    return this.queue.listTasks();
209	  }
210	
211	  // ---------- 普通交易提交（行为与既有流程一致，载荷不含策略版本） ----------
212	
213	  submitTransaction(sub: TransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
214	    // 原始值透传，由 submit 统一做安全转换，避免在入口抛出原生 TypeError
215	    return this.submit(
216	      'transaction',
217	      {
218	        nonce: sub.nonce,
219	        deadline: sub.deadline,
220	        to: sub.to,
221	        value: sub.value,
222	        data: sub.data ?? new Uint8Array(),
223	      },
224	      signatures,
225	    );
226	  }
227	
228	  // ---------- 原子批量普通交易提交 ----------
229	
230	  /**
231	   * 提交一个有序调用列表作为单个原子批量任务。
232	   *
233	   * 摘要使用 safe-wallet/tx-batch/v1 域标签，绑定钱包标识、nonce、截止时间与按顺序编码的
234	   * 全部调用：单笔交易 / 策略变更 / 取消签名都不能授权批量交易；任一调用的收款方、金额、
235	   * data 或调用顺序、项数变化都会改变摘要。
236	   *
237	   * 校验顺序与单笔提交一致（任一失败都不建任务、不消费 nonce、不改策略/队列）：
238	   *   1) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
239	   *   2) deadline 早于当前时间 → RequestExpired
240	   *   3) 列表（1..64 项）、收款地址、金额、data、nonce 顺序、阈值签名 → InvalidTransactionBatch
241	   *
242	   * 成功时只入队一个批量任务、只消费本次 nonce 并推进 expectedNonce。
243	   */
244	  submitBatchTransaction(sub: BatchTransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
245	    return this.submit(
246	      'transaction-batch',
247	      {
248	        nonce: sub.nonce,
249	        deadline: sub.deadline,
250	        calls: sub.calls,
251	      },
252	      signatures,
253	    );
254	  }
255	
256	  // ---------- 策略变更提交 ----------
257	
258	  proposePolicyChange(sub: PolicyChangeSubmission, signatures: readonly Uint8Array[]): WalletTask {
259	    return this.submit(
260	      'policy-change',
261	      {
262	        version: sub.version,
263	        nonce: sub.nonce,
264	        deadline: sub.deadline,
265	        newOwners: sub.newOwners,
266	        newConfirmations: sub.newConfirmations,
267	      },
268	      signatures,
269	    );
270	  }
271	
272	  // ---------- 任务取消 ----------
273	
274	  /**
275	   * 取消一个尚未执行的 queued 任务。
276	   *
277	   * 取消摘要使用 safe-wallet/cancel/v1 域标签，绑定钱包标识、目标任务 digest、nonce 与
278	   * 截止时间：签名无法改绑其他任务、其他钱包或其他时间窗口。
279	   *
280	   * 校验顺序（任一失败都不改变任务、不消费 nonce、不改变策略）：
281	   *   1) 字段非法 → InvalidCancellation
282	   *   2) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
283	   *   3) deadline 早于当前时间 → RequestExpired
284	   *   4) nonce 顺序（须等于 expectedNonce）→ InvalidCancellation
285	   *   5) 目标不存在 → TaskNotFoundError；目标已终态 → TaskCancellationConflict
286	   *   6) 阈值签名（当前所有者、去重后达到当前确认数）→ InvalidCancellation
287	   *
288	   * 成功时目标任务由 queued 进入 cancelled 终态并返回：保留原 payload/digest/nonce，
289	   * 记录取消时间与取消摘要；不执行目标效果，不改变 owners/确认数/策略版本，
290	   * 只消费本次 nonce 并推进 expectedNonce。取消不要求任务在队首，也不调整队列顺序。
291	   */
292	  cancelTask(
293	    taskId: string,
294	    nonce: bigint | number,
295	    deadline: bigint | number,
296	    signatures: readonly Uint8Array[],
297	  ): WalletTask;
298	  cancelTask(sub: CancellationSubmission, signatures: readonly Uint8Array[]): WalletTask;
299	  cancelTask(
300	    a: string | CancellationSubmission,
301	    b: readonly Uint8Array[] | bigint | number,
302	    c?: bigint | number,
303	    d?: readonly Uint8Array[],
304	  ): WalletTask {
305	    const sub: CancellationSubmission =
306	      typeof a === 'string' || a === undefined || a === null
307	        ? { taskId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
308	        : a;
309	    const signatures: readonly Uint8Array[] =
310	      (typeof a === 'string' || a === undefined || a === null ? d : (b as readonly Uint8Array[])) ??
311	      ([] as readonly Uint8Array[]);
312	
313	    // (1) 字段安全转换（畸形输入只抛 InvalidCancellation）
314	    const nonce = toBigInt(sub.nonce, InvalidCancellation, 'nonce');
315	    if (!isNonNegativeInteger(nonce)) {
316	      throw new InvalidCancellation('nonce must be a non-negative integer');
317	    }
318	    // (2) nonce 复用优先于过期判定
319	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
320	
321	    const deadline = toBigInt(sub.deadline, InvalidCancellation, 'deadline');
322	    if (!isNonNegativeInteger(deadline)) throw new InvalidCancellation('deadline out of range');
323	    // (3) 截止时间
324	    if (deadline < this.now()) {
325	      throw new RequestExpired(`request deadline ${deadline} already passed`);
326	    }
327	    // (4) nonce 顺序：取消与提交共用同一严格递增序列
328	    if (nonce !== this.nextNonce) {
329	      throw new InvalidCancellation(`expected nonce ${this.nextNonce}, got ${nonce}`);
330	    }
331	
332	    // (5) 目标任务状态
333	    const taskId = sub.taskId;
334	    if (typeof taskId !== 'string' || taskId.length === 0) {
335	      throw new InvalidCancellation('taskId must be a non-empty string');
336	    }
337	    const target = this.queue.getTask(taskId);
338	    if (target === null) throw new TaskNotFoundError(`task not found: ${taskId}`);
339	    if (target.status !== 'queued') {
340	      throw new TaskCancellationConflict(`task ${taskId} is already ${target.status}`);
341	    }
342	
343	    // (6) 阈值签名：摘要绑定钱包标识、目标任务 digest、nonce、deadline
344	    const digest = hashCancellation({
345	      walletId: this.id,
346	      taskDigest: target.digest,
347	      nonce,
348	      deadline,
349	    });
350	    this.verifyThresholdSignatures(digest, signatures, InvalidCancellation);
351	
352	    // 原子生效：目标任务进入 cancelled 终态 + 消费 nonce；策略与队列顺序不变
353	    const cancelled = this.queue.cancel(taskId, this.now(), digest.toString('hex'));
354	    this.usedNonces.add(nonce);
355	    this.nextNonce = nonce + 1n;
356	    return cancelled;
357	  }
358	
359	  // ---------- 执行 ----------
360	
361	  executeTask(taskId: string): WalletTask {
362	    return this.queue.execute(taskId, this.now());
363	  }
364	
365	  executeNext(): WalletTask | null {
366	    return this.queue.executeNext(this.now());
367	  }
368	
369	  getTask(taskId: string): WalletTask | null {
370	    return this.queue.getTask(taskId);
371	  }
372	
373	  // ============================================================
374	  // 内部实现
375	  // ============================================================
376	
377	  /**
378	   * 统一提交入口。raw 接收未经转换的原始标量（bigint/number/string），
379	   * 所有转换与字段合法性判定都在这里完成，保证只能抛出约定错误类型。
380	   */
381	  private submit(
382	    kind: WalletTaskPayload['kind'],
383	    raw: Record<string, unknown>,
384	    signatures: readonly Uint8Array[],
385	  ): WalletTask {
386	    const Invalid =
387	      kind === 'policy-change'
388	        ? InvalidPolicyChange
389	        : kind === 'transaction-batch'
390	          ? InvalidTransactionBatch
391	          : InvalidTransaction;
392	
393	    // 校验优先级（任一失败都不建任务、不消费 nonce、不改策略）：
394	    //   1) nonce 复用 → 既有重放防护的公开异常（旧请求重放即使已过期也仍报复用）
395	    //   2) 截止时间早于当前时间 → RequestExpired
396	    //   3) 字段 / 版本 / nonce 顺序 / 签名 → 对应 Invalid*
397	    const nonce = toBigInt(raw.nonce, Invalid, 'nonce');
398	    if (!isNonNegativeInteger(nonce)) throw new Invalid('nonce must be a non-negative integer');
399	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
400	
401	    const deadline = toBigInt(raw.deadline, Invalid, 'deadline');
402	    if (!isNonNegativeInteger(deadline)) throw new Invalid('deadline out of range');
403	    if (deadline < this.now()) {
404	      throw new RequestExpired(`request deadline ${deadline} already passed`);
405	    }
406	    if (nonce !== this.nextNonce) throw new Invalid(`expected nonce ${this.nextNonce}, got ${nonce}`);
407	
408	    // (3) 字段校验 + 规范化
409	    let payload: WalletTaskPayload;
410	    let digest: Buffer;
411	    if (kind === 'transaction') {
412	      const to = normalizeAddress(raw.to as string);
413	      if (to === null || isZeroAddress(to)) throw new Invalid('invalid or zero recipient address');
414	      const value = toBigInt(raw.value, Invalid, 'value');
415	      if (!isNonNegativeInteger(value)) throw new Invalid('value out of range');
416	      const dataField = raw.data;
417	      if (
418	        dataField !== undefined &&
419	        !(dataField instanceof Uint8Array) &&
420	        !ArrayBuffer.isView(dataField)
421	      ) {
422	        throw new Invalid('data must be a byte array');
423	      }
424	      const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
425	      const req: TransactionRequest = {
426	        walletId: this.id,
427	        nonce,
428	        deadline,
429	        to,
430	        value,
431	        data,
432	      };
433	      digest = hashTransaction(req);
434	      payload = { kind: 'transaction', deadline, to, value, data };
435	    } else if (kind === 'transaction-batch') {
436	      // 有序调用列表：1..64 项；逐项规范化收款地址、金额与 data（顺序保持不变）
437	      const calls = this.normalizeBatchCalls(raw.calls);
438	      const req: TransactionBatchRequest = {
439	        walletId: this.id,
440	        nonce,
441	        deadline,
442	        calls,
443	      };
444	      digest = hashTransactionBatch(req);
445	      payload = { kind: 'transaction-batch', deadline, calls };
446	    } else {
447	      const version = toBigInt(raw.version, InvalidPolicyChange, 'version');
448	      // (3a) 版本必须绑定当前版本（提交时不匹配 → InvalidPolicyChange；执行时漂移 → PolicyConflict）
449	      if (version !== this.version) {
450	        throw new InvalidPolicyChange(
451	          `policy version mismatch: bound ${version}, current ${this.version}`,
452	        );
453	      }
454	      // (3b) 以当前版本为基准验证新策略
455	      const newOwners = normalizeOwnerList(raw.newOwners as string[], InvalidPolicyChange);
456	      const newConfirmations = toBigInt(raw.newConfirmations, InvalidPolicyChange, 'newConfirmations');
457	      if (newConfirmations <= 0n || newConfirmations > BigInt(newOwners.length)) {
458	        throw new InvalidPolicyChange(
459	          `new confirmations must be within 1..new owners (${newOwners.length}), got ${newConfirmations}`,
460	        );
461	      }
462	      const req: PolicyChangeRequest = {
463	        walletId: this.id,
464	        version,
465	        nonce,
466	        deadline,
467	        newOwners,
468	        newConfirmations,
469	      };
470	      digest = hashPolicyChange(req);
471	      payload = { kind: 'policy-change', deadline, version, newOwners, newConfirmations };
472	    }
473	
474	    // (4) 阈值签名：恢复 → 去重 → 必须为当前所有者 → 数量达到当前确认数
475	    this.verifyThresholdSignatures(digest, signatures, Invalid);
476	
477	    // (5) 原子生效（到队列为止）：入队 + 消费 nonce。
478	    //     入队失败（同一摘要重复等）时不消费 nonce。
479	    let task: WalletTask;
480	    try {
481	      task = this.queue.enqueue({
482	        nonce,
483	        digest: digest.toString('hex'),
484	        payload,
485	        submittedAt: this.now(),
486	      });
487	    } catch (err) {
488	      if (err instanceof InvalidQueueStateError) throw new Invalid(err.message);
489	      throw err;
490	    }
491	    this.usedNonces.add(nonce);
492	    this.nextNonce = nonce + 1n;
493	    return task;
494	  }
495	
496	  /**
497	   * 规范化批量调用列表：必须是 1..MAX_BATCH_CALLS 项的数组，每项是对象，
498	   * 收款地址合法且非零、金额为 256 位以内非负整数、data 必须是 Uint8Array。
499	   * 保持输入顺序；任何畸形都归为 InvalidTransactionBatch。
500	   */
501	  private normalizeBatchCalls(rawCalls: unknown): BatchCall[] {
502	    if (!Array.isArray(rawCalls) || rawCalls.length === 0) {
503	      throw new InvalidTransactionBatch('calls must be a non-empty array');
504	    }
505	    if (rawCalls.length > MAX_BATCH_CALLS) {
506	      throw new InvalidTransactionBatch(`too many calls: ${rawCalls.length} > ${MAX_BATCH_CALLS}`);
507	    }
508	    const calls: BatchCall[] = [];
509	    for (const rawCall of rawCalls) {
510	      if (typeof rawCall !== 'object' || rawCall === null) {
511	        throw new InvalidTransactionBatch('each batch call must be an object');
512	      }
513	      const call = rawCall as Record<string, unknown>;
514	      const to = normalizeAddress(call.to as string);
515	      if (to === null || isZeroAddress(to)) {
516	        throw new InvalidTransactionBatch('invalid or zero recipient address in batch call');
517	      }
518	      const value = toBigInt(call.value, InvalidTransactionBatch, 'value');
519	      if (!isNonNegativeInteger(value)) {
520	        throw new InvalidTransactionBatch('batch call value out of range');
521	      }
522	      if (!(call.data instanceof Uint8Array)) {
523	        throw new InvalidTransactionBatch('batch call data must be a Uint8Array');
524	      }
525	      // 复制一份，避免入队后调用方再改动同一缓冲区影响任务内容/摘要
526	      calls.push({ to, value, data: Buffer.from(call.data) });
527	    }
528	    return calls;
529	  }
530	
531	  /** 按“当前策略”的所有者集合与确认数校验签名收集 */
532	  private verifyThresholdSignatures(
533	    digest: Uint8Array,
534	    signatures: readonly Uint8Array[],
535	    Invalid: new (msg: string) => Error,
536	  ): void {
537	    if (!Array.isArray(signatures)) {
538	      throw new Invalid('signatures must be an array');
539	    }
540	    if (signatures.length === 0) throw new Invalid('missing signatures');
541	
542	    const signedBy = new Set<Address>();
543	    for (const sig of signatures) {
544	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
545	        throw new Invalid('each signature must be a 65-byte r||s||v blob');
546	      }
547	      const signer = recoverAddress(digest, Uint8Array.from(sig));
548	      if (signer === null) throw new Invalid('malformed or non-canonical signature');
549	      if (!this.ownerSet.has(signer)) {
550	        // 非所有者签名：既可能是伪造，也可能是签名载荷与提交内容不匹配
551	        throw new Invalid('signature does not match payload or signer is not an owner');
552	      }
553	      signedBy.add(signer); // 地址去重：同一所有者多签只计一次
554	    }
555	    if (BigInt(signedBy.size) < this.confirmations) {
556	      throw new Invalid(
557	        `threshold not met: need ${this.confirmations} distinct owners, got ${signedBy.size}`,
558	      );
559	    }
560	  }
561	
562	  /** 队列执行器回调：定义各类任务的生效语义 */
563	  private applyTask(task: WalletTask): unknown {
564	    const p = task.payload;
565	    if (p.kind === 'transaction') {
566	      // 普通交易既有执行结果：一个可观察的执行产物；不触碰策略状态。
567	      // 截止时间只在提交阶段核对（RequestExpired），不作为执行闸门，以保持既有执行结果不变。
568	      return {
569	        kind: 'transfer',
570	        to: p.to,
571	        value: p.value,
572	        data: Buffer.from(p.data).toString('hex'),
573	      };
574	    }
575	
576	    if (p.kind === 'transaction-batch') {
577	      // 原子批量：执行器一次性产出整批回执。调用方（队列）在本回调正常返回后才写入
578	      // executed 终态；本回调抛出则整批进入 failed，不产生部分执行回执。
579	      // 截止时间同样不是执行闸门，与单笔普通交易保持一致。
580	      return {
581	        kind: 'transfer-batch',
582	        calls: p.calls.map((call) => ({
583	          to: call.to,
584	          value: call.value,
585	          data: Buffer.from(call.data).toString('hex'),
586	        })),
587	      };
588	    }
589	
590	    // 策略变更：仅当绑定版本仍等于当前版本时生效
591	    if (p.version !== this.version) {
592	      throw new PolicyConflict(
593	        `policy version drifted: task bound ${p.version}, current ${this.version}`,
594	      );
595	    }
596	    // 所有者集合与确认数同时替换；版本恰好递增一次
597	    this.owners = [...p.newOwners];
598	    this.ownerSet.clear();
599	    for (const o of this.owners) this.ownerSet.add(o);
600	    this.confirmations = p.newConfirmations;
601	    this.version += 1n;
602	    return {
603	      kind: 'policy-applied',
604	      version: this.version,
605	      owners: [...this.owners],
606	      confirmations: this.confirmations,
607	    };
608	  }
609	}
610	
611	// ---------- 所有者列表规范化（空/重复/零地址校验） ----------
612	
613	function normalizeOwnerList(
614	  input: readonly string[],
615	  ErrorCtor: typeof InvalidPolicyChange | typeof InvalidTransaction = InvalidPolicyChange,
616	): Address[] {
617	  if (!Array.isArray(input) || input.length === 0) {
618	    throw new ErrorCtor('owners list must be a non-empty array');
619	  }
620	  const out: Address[] = [];
621	  const seen = new Set<Address>();
622	  for (const raw of input) {
623	    const addr = normalizeAddress(raw);
624	    if (addr === null) throw new ErrorCtor(`invalid owner address: ${String(raw)}`);
625	    if (addr === ZERO_ADDRESS || isZeroAddress(addr)) {
626	      throw new ErrorCtor('zero address is not allowed as owner');
627	    }
628	    if (seen.has(addr)) throw new ErrorCtor(`duplicate owner: ${addr}`);
629	    seen.add(addr);
630	    out.push(addr);
631	  }
632	  return out;
633	}
